ValidationRule.errorConditionFormula:
(
  BEGINS(Student_ID__c  , 'C') &&
  RecordType.Name = 'Student Account' &&
  (
    (
      ISNEW() &&
      (
        ISBLANK(TEXT(Come_From_Province__c)) ||
        ISBLANK(TEXT(Come_From_City__c))
      )
    ) ||
    (
      ISNEW() == FALSE && 
      (
        (
          ISCHANGED(Come_From_Province__c) &&
          ISBLANK(TEXT(Come_From_Province__c))
        ) ||
        (
          ISCHANGED(Come_From_City__c) &&
          ISBLANK(TEXT(Come_From_City__c))
        )
      )
    )
  )
)
